module wheel_rotation (\n    input [1:0] wheel0 [0:7],\n    input [1:0] wheel1 [0:7],\n    input [1:0] wheel2 [0:7],\n    output reg [4:0] result\n);\n    reg [3:0] min_cost;\n    integer r0, r1, r2, j;\n    reg [2:0] idx0, idx1, idx2;\n    reg [1:0] a, b, c;\n    reg valid;\n    reg [3:0] cost_r0, cost_r1, cost_r2, total_cost;\n\n    always @* begin\n        min_cost = 4'd15;\n        for (r0 = 0; r0 < 8; r0 = r0 + 1) begin\n            for (r1 = 0; r1 < 8; r1 = r1 + 1) begin\n                for (r2 = 0; r2 < 8; r2 = r2 + 1) begin\n                    cost_r0 = (r0 <= 4) ? r0 : (8 - r0);\n                    cost_r1 = (r1 <= 4) ? r1 : (8 - r1);\n                    cost_r2 = (r2 <= 4) ? r2 : (8 - r2);\n                    total_cost = cost_r0 + cost_r1 + cost_r2;\n                    valid = 1'b1;\n                    for (j = 0; j < 8; j = j + 1) begin\n                        idx0 = (j + r0) % 8;\n                        idx1 = (j + r1) % 8;\n                        idx2 = (j + r2) % 8;\n                        a = wheel0[idx0];\n                        b = wheel1[idx1];\n                        c = wheel2[idx2];\n                        if (a == b || a == c || b == c) begin\n                            valid = 1'b0;\n                        end\n                    end\n                    if (valid && (total_cost < min_cost)) begin\n                        min_cost = total_cost;\n                    end\n                end\n            end\n        end\n        if (min_cost == 4'd15) begin\n            result = 5'b11111;\n        end else begin\n            result = {1'b0, min_cost};\n        end\n    end\nendmodule